<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$id=(int)($_GET['id']??0);$pdo=db();$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND seller_id=?');$s->execute([$id,$sid]);$p=$s->fetch();if(!$p){flash('error','Listing not found.');redirect('seller/products.php');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$price=(float)post('price');$stock=(float)post('stock');$min=(float)post('min_quantity');if(!post('name')||$price<=0||$stock<0||$min<=0||($stock>0&&$min>$stock))$error='Check required values and stock quantities.';else{$old=$p['image_path'];$image=$old;try{if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];$type=mime_content_type($f['tmp_name']);if($f['error']||$f['size']>MAX_UPLOAD||!in_array($type,['image/jpeg','image/png','image/webp'],true))throw new Exception('Upload a JPG, PNG, or WebP image under 2 MB.');if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$type];$filename=bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$filename))throw new Exception('Could not save the image. Check uploads/products permissions.');$image='uploads/products/'.$filename;}elseif(isset($_POST['remove_image']))$image=null;$pdo->prepare('UPDATE products SET category_id=?,name=?,description=?,image_path=?,price=?,stock=?,min_quantity=?,freshness_info=?,is_available=? WHERE id=? AND seller_id=?')->execute([(int)post('category_id'),post('name'),post('description'),$image,$price,$stock,$min,post('freshness_info'),isset($_POST['is_available']),$id,$sid]);if($old!==$image)delete_product_upload($old);flash('success','Listing updated.');redirect('seller/products.php');}catch(Throwable $e){$error=$e->getMessage();}}}$pageTitle='Edit listing';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER CATALOGUE</p><h1>Edit <?=e($p['name'])?></h1></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><?php require 'product-form.php';require '../includes/footer.php'; ?>
